wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds maximum length".to_string(),
            });
        }

        let system = "You are a customer support assistant. Use the provided knowledge to answer the question. You may call the 'lookup' tool to search the knowledge base if needed.";
        let prompt = format!(
            "Question: {}\n\nKnowledge:\n{}",
            ctx.question,
            ctx.knowledge.join("\n")
        );

        match tool_llm::generate(system, &prompt) {
            Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
            Reply::Call(req) => {
                if req.tool == "lookup" {
                    let results = kb_read::lookup(&req.query);
                    let text = if results.is_empty() {
                        "No information found.".to_string()
                    } else {
                        results.join("\n")
                    };
                    ResponseResult::Ok(AgentResponse { text })
                } else {
                    ResponseResult::Error(LlmError {
                        message: format!("unsupported tool requested: {}", req.tool),
                    })
                }
            }
        }
    }
}

export!(Node);
